// The chart itself is SVG, so it has its own accessible selection handler.
document.addEventListener('click',ev=>{const target=ev.target.closest('[data-month]');if(target&&dashboardAccessible()){persistDraft();state.period=target.dataset.month;state.year=Number(state.period.slice(0,4));state.followLatest=false;state.page=0;fillFilters();render();}});
