for(const [id,key]of [['period-filter','period'],['region-filter','region'],['district-filter','district'],['impact-filter','service_impact'],['vendor-filter','vendor'],['severity-filter','severity'],['label-filter','site_label'],['cause-filter','root_cause'],['year-filter','year'],['week-filter','week']])$('#'+id).addEventListener('change',ev=>{if(key==='period'&&(!ev.target.value||!coverageFor(data?.meta||{},ev.target.value))){ev.target.value=state.period;toast('Choose a month within the loaded source coverage.');return;}persistDraft();reviewToken++;state[key]=['year','week'].includes(key)&&ev.target.value!=='all'?Number(ev.target.value):ev.target.value;if(['period','year','week'].includes(key)){state.followLatest=false;if(key==='period')state.year=Number(state.period.slice(0,4));if(key==='year'){state.period=String(state.year)+state.period.slice(4);if(state.week!=='all')state.week=Math.min(state.week,weeksInYear(state.year));}}state.site_id='all';state.page=0;if(key==='region')state.district='all';fillFilters();render();});
