async function startup(){
  fillIcons();$('#print-review').disabled=true;
  if(titles[location.hash.slice(1)]){state.view=location.hash.slice(1);if(REPORTS[state.view])state.reportView=state.view;}
  const {key,url}=configuredConnection();
  if(key){try{db=new PerformanceDatabase(url,key);if(db.session){authBusy=true;notice(`<span class="spinner"></span><span>Restoring your performance session…</span>`);render();await loadDatabase();history.replaceState(null,'','#'+state.view);return;}}catch(err){connectionError=err.message;notice(`${icon('alert')}<span>${e(err.message)}</span>`,'warn');toast(err.message);}finally{authBusy=false;render();}}
  if(config.privateSnapshot){try{const r=await fetch(config.privateSnapshot);if(!r.ok)throw new Error('The private source snapshot could not be loaded.');const blob=await r.blob(),head=new Uint8Array(await blob.slice(0,2).arrayBuffer());const text=head[0]===31&&head[1]===139?await new Response(blob.stream().pipeThrough(new DecompressionStream('gzip'))).text():await blob.text();setData(JSON.parse(text),'snapshot');return;}catch(err){toast(err.message);}}
  notice(`${icon('lock')}<span>${e(connectionError||(key?'Sign in to load the latest performance data.':'Connect your PostgreSQL project to load performance records.'))}</span>`,connectionError?'warn':'');render();
}
